	// Calculate if there are any relevant incoming changes

	// There are unsaved changes . This can be detected by calling tw.system.coachUtils.hasLocallyChangedInputVars(). Here, however, this variable is
	// set by the Data Section coach view when it detects that a child view's data binding has changed.
	if(tw.local.unsavedLocalChanges === true || tw.system.coachUtils.hasLocallyChangedInputVars()){
		
		if(!tw.local.unsavedLocalChanges)
			tw.local.unsavedLocalChanges = true;
			
		// Call the helper function to update the incoming and local changes.
		checkIncomingChanges(tw.local, tw.system.coachUtils.getLocallyChangedVars(), tw.system.dataChangeUtils.getIncomingVars())		 
		
	} else if(tw.system.coachUtils.getLocallyChangedVars().length > 0) { // No pending changes to be merged, or local changes
	
		// Apply incoming changes to the local variables.
		tw.system.dataChangeUtils.applyAllIncomingVars();
		tw.local.incomingChangesMerged = true; // Signal that changes were applied automatically. The Data Section can listen and pop up a notification.
	 
	}

}); "]}},{"targetRef":"2025.d33a055d-a413-4124-bac6-df51ee6a9337","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Collect change information","declaredType":"sequenceFlow","id":"2027.1f24a331-acd3-473e-ae3c-4d92f781a700","sourceRef":"2025.9ce92c41-c30b-4def-a2f0-4c8d22e4d071"},{"targetRef":"2025.a17dd549-a1d3-4b36-8529-0b76bc56a8d7","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Stay on page","declaredType":"sequenceFlow","id":"2027.0dfb4e8b-bbc7-4ddc-accc-9520f0be9c63","sourceRef":"2025.d33a055d-a413-4124-bac6-df51ee6a9337"}],"startQuantity":1,"extensionElements":{"nodeVisualInfo":[{"width":95,"x":51,"y":463,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Data Change","triggeredByEvent":true,"isForCompensation":false,"completionQuantity":1,"declaredType":"subProcess","id":"2025.3724fa76-c258-43a4-987c-e73b3832bec1"},{"targetRef":"2025.925040f3-64a1-44d5-9de6-a6cd839127d3","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"topCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":true}]},"name":"Yes","declaredType":"sequenceFlow","id":"2027.5803da3b-94fc-4122-830a-c6a7d7367066","sourceRef":"2025.51699ba7-4591-4237-b717-5fd3416d1ff7"},{"startQuantity":1,"outgoing":["2027.58292925-55c8-4ca7-9bcd-9056885727bf"],"incoming":["2027.3ec7adbd-d3a3-41a8-b193-a59415178d72"],"default":"2027.58292925-55c8-4ca7-9bcd-9056885727bf","extensionElements":{"nodeVisualInfo":[{"width":95,"x":523,"y":103,"declaredType":"TNodeVisualInfo","height":70}]},"name